import {
	type BranchTuning,
	type BucketAccessLevel,
	type ComputeSettings,
	type Config,
	createNeonApiFromOptions,
	type DataApiExternalAuthConfig,
	type DataApiInput,
	ErrorCode,
	type NeonApi,
	type NeonBranchSnapshot,
	type NeonBucketSnapshot,
	type NeonCredentialMeta,
	type NeonDataApiSnapshot,
	type NeonDatabaseSnapshot,
	type NeonEndpointSnapshot,
	type NeonFunctionSnapshot,
	type NeonProjectSnapshot,
	type NeonRealtimeSnapshot,
	PlatformError,
} from "@neon/config";

export interface PullConfigOptions {
	/** Neon project id (`<project>`). Required — the API addresses branches by project. */
	projectId: string;
	/** Neon branch id (`br-…`). Required. Resolve names to ids before calling. */
	branchId: string;
	/** Neon API key. Falls back to `NEON_API_KEY` / neonctl credentials. */
	apiKey?: string;
	/** Neon API base URL. Falls back to `NEON_API_HOST`, then production. */
	apiHost?: string;
	/** Inject a custom NeonApi adapter (primarily for tests). */
	api?: NeonApi;
	/** Read the branch's Realtime state. Defaults to `true`. */
	realtime?: boolean;
}

/**
 * Live Preview-feature state read back from a branch. Surfaced alongside `config` rather
 * than inside it because functions cannot round-trip: the remote only knows the deployed
 * bundle, not the local `source` path a {@link FunctionConfig} requires, so a pulled
 * function is reported as `{ slug, name }` (no `source`).
 */
export interface PulledPreview {
	buckets: Array<{ name: string; access: BucketAccessLevel }>;
	functions: Array<{ slug: string; name: string }>;
	/**
	 * Secret-free metadata for the credentials issued on the branch (Preview). Surfaced so
	 * `config status` can show issued credentials (id, scopes, last used) without ever
	 * exposing the one-time `api_token` / `s3_secret_access_key`. Empty when none / the
	 * credentials endpoint is unavailable for the project.
	 */
	credentials: NeonCredentialMeta[];
}

export interface PulledBranchConfig {
	project: {
		id: string;
		name: string;
		region: string;
		pgVersion: number;
		orgId?: string;
	};
	branch: {
		id: string;
		name: string;
		parent?: string;
		isDefault: boolean;
		protected: boolean;
		expiresAt?: string;
	};
	/**
	 * The branch's live state expressed as a {@link Config}: static `auth` / `dataApi`
	 * toggles, Realtime under `preview.realtime`, any object-storage `preview.buckets`, plus
	 * a `branch` closure carrying the
	 * branch's lifecycle/compute tuning. Buckets are included here (not just in
	 * {@link PulledBranchConfig.preview}) because they round-trip cleanly — name + access
	 * level is all a {@link Config} needs — so the no-policy env path (`neon dev` /
	 * `neon env pull`) can resolve the branch's storage credentials without a local
	 * `neon.ts`. Preview **functions** are reported only in
	 * {@link PulledBranchConfig.preview}: they cannot round-trip (the remote has no local
	 * `source` path). The AI Gateway is omitted from both — it has no branch-level "enabled"
	 * state to read back (it is always available, credential-gated), so `pullConfig` cannot
	 * tell whether a policy would enable it.
	 */
	config: Config;
	/**
	 * Live Preview-feature state, when the branch has any buckets/functions or issued
	 * credentials. Omitted entirely when there is nothing to report. The AI Gateway is not
	 * included: it is always available (credential-gated), not per-branch state.
	 */
	preview?: PulledPreview;
}

export async function pullConfig(
	options: PullConfigOptions,
): Promise<PulledBranchConfig> {
	const api = options.api ?? createApiFromOptions(options);
	const projectId = options.projectId;
	const branchId = options.branchId;
	const getRealtime =
		options.realtime === false
			? undefined
			: api.getProjectBranchRealtime?.bind(api);

	// The first three stages need only the project and branch ids, so they start together.
	// They are awaited in the order they used to run, so the first error reported is the same
	// one as before (project, then branches/endpoints, then the branch lookup, then databases).
	const projectRead = started(() => api.getProject(projectId));
	const listsRead = started(() =>
		Promise.all([
			started(() => api.listBranches(projectId)),
			started(() => api.listEndpoints(projectId)),
		]),
	);
	// Data API is enabled per branch + database, so resolve a database to probe.
	const databasesRead = started(() =>
		api.listBranchDatabases(projectId, branchId),
	);
	// Preview reads degrade to "none / disabled" when the feature isn't available for the
	// project/region. `pullConfig` mirrors the branch for env resolution (`neon dev`,
	// `neon env pull`) and `inspect` — an unavailable Preview feature should not break those
	// (env comes from auth/dataApi/postgres). `pushConfig` is the place that fails on an
	// unavailable feature, and only when the policy declares it.
	// The group starts together once databases resolve (the Data API probe needs one), as
	// before, so which member's error comes first is unchanged.
	const previewRead = started(() =>
		databasesRead.then((databases) => {
			const probeDatabase = pickProbeDatabase(databases);
			return Promise.all([
				started(() =>
					degradeUnavailable(
						() => api.listBranchBuckets(projectId, branchId),
						[],
					),
				),
				started(() =>
					degradeUnavailable(
						() => api.listBranchFunctions(projectId, branchId),
						[],
					),
				),
				started(() =>
					degradeUnavailable(
						() => api.listCredentials(projectId, branchId),
						[],
					),
				),
				started(() => api.getNeonAuth(projectId, branchId)),
				started(() =>
					probeDatabase
						? api.getNeonDataApi(projectId, branchId, probeDatabase)
						: Promise.resolve(null),
				),
				started(() =>
					getRealtime
						? degradeUnavailable(
								() => getRealtime(projectId, branchId),
								null,
							)
						: Promise.resolve(null),
				),
			]);
		}),
	);

	const project = await projectRead;
	const [branches, endpoints] = await listsRead;
	const branch = resolveBranch(branchId, branches);
	const endpoint = endpoints.find(
		(ep) => ep.type === "read_write" && ep.branchId === branch.id,
	);
	await databasesRead;
	const [buckets, functions, credentials, auth, dataApi, realtime] =
		await previewRead;

	return buildPulledBranchConfig(project, branch, branches, endpoint, {
		buckets,
		functions,
		credentials,
		authEnabled: auth !== null,
		dataApiEnabled: dataApi !== null,
		dataApi,
		realtime,
	});
}

/**
 * The `dataApi` a pulled policy declares for a live Data API. The provider is fixed when the
 * Data API is created, so a bare `true` (Neon Auth) is only right when that is what the
 * branch has; writing it over an external-IdP Data API would make the next apply enable Neon
 * Auth. When the API does not report the provider (older Data APIs), the branch's Neon Auth
 * state is the best available answer: with Neon Auth off, the Data API cannot be using it.
 */
export function pulledDataApiConfig(
	dataApi: NeonDataApiSnapshot,
	authEnabled: boolean,
): DataApiInput {
	const external = (): DataApiExternalAuthConfig => {
		const config: DataApiExternalAuthConfig = { authProvider: "external" };
		if (dataApi.jwksUrl !== undefined) config.jwksUrl = dataApi.jwksUrl;
		if (dataApi.providerName !== undefined)
			config.providerName = dataApi.providerName;
		if (dataApi.jwtAudience !== undefined)
			config.jwtAudience = dataApi.jwtAudience;
		return config;
	};
	switch (dataApi.authProvider) {
		case "neon_auth":
			return true;
		case "external":
			return external();
		default:
			// "none" has no policy spelling; `external` without a JWKS declares the Data API
			// while leaving Neon Auth alone, which is the one thing a provider-less Data API
			// and an unknown one have in common.
			return authEnabled ? true : external();
	}
}

/**
 * Starts a read now and keeps an unread rejection from crashing the process; the caller
 * awaits it (and sees the error) when its turn comes. Also turns a synchronous throw from
 * a custom adapter into a rejection.
 */
function started<T>(read: () => Promise<T>): Promise<T> {
	const promise = Promise.resolve().then(read);
	promise.catch(() => undefined);
	return promise;
}

/**
 * Pick the database to probe for a Data API integration. Data API is enabled per
 * branch + database; for read-back we only need to know whether *any* database has it
 * on, so prefer the conventional default (`neondb`) and otherwise fall back to the first
 * database. Returns `undefined` when the branch has no databases.
 */
function pickProbeDatabase(
	databases: NeonDatabaseSnapshot[],
): string | undefined {
	if (databases.length === 0) return undefined;
	const byName = databases.find((d) => d.name === "neondb");
	if (byName) return byName.name;
	return databases[0].name;
}

/**
 * Run a Preview-feature read, returning `fallback` if the feature is unavailable for the
 * project/region. Most adapters report {@link ErrorCode.FeatureUnavailable}; API hosts where
 * a route is not deployed can instead return a generic 404. The project and branch are
 * validated independently by `pullConfig`, so that route-level 404 is also safe to degrade.
 * Other errors propagate. This lets a branch without a Preview feature still mirror cleanly
 * for env resolution / `inspect`, rather than aborting on an unrelated capability.
 */
async function degradeUnavailable<T>(
	read: () => Promise<T>,
	fallback: T,
): Promise<T> {
	try {
		return await read();
	} catch (err) {
		if (
			err instanceof PlatformError &&
			(err.code === ErrorCode.FeatureUnavailable ||
				(err.code === ErrorCode.NotFound && err.details.status === 404))
		) {
			return fallback;
		}
		throw err;
	}
}

function createApiFromOptions(options: PullConfigOptions): NeonApi {
	return createNeonApiFromOptions("pullConfig", {
		...(options.apiKey ? { apiKey: options.apiKey } : {}),
		...(options.apiHost ? { apiHost: options.apiHost } : {}),
	});
}

export function buildPulledBranchConfig(
	project: NeonProjectSnapshot,
	branch: NeonBranchSnapshot,
	branches: NeonBranchSnapshot[],
	endpoint: NeonEndpointSnapshot | undefined,
	previewState?: {
		buckets: NeonBucketSnapshot[];
		functions: NeonFunctionSnapshot[];
		credentials?: NeonCredentialMeta[];
		/** Whether a Neon Auth integration is enabled on the branch. */
		authEnabled?: boolean;
		/** Whether a Neon Data API integration is enabled on the branch. */
		dataApiEnabled?: boolean;
		/**
		 * The live Data API, when enabled. Its auth provider decides the shape of the emitted
		 * `dataApi` (see {@link pulledDataApiConfig}); with only `dataApiEnabled` the policy
		 * falls back to a bare `true`.
		 */
		dataApi?: NeonDataApiSnapshot | null;
		/** Realtime state when the adapter supports the branch endpoint. */
		realtime?: NeonRealtimeSnapshot | null;
	},
): PulledBranchConfig {
	const parent = branch.parentId
		? branches.find((b) => b.id === branch.parentId)
		: undefined;
	// Auth and Data API are static top-level toggles, while Realtime is static under
	// `preview.realtime`. A config pulled from a branch with them enabled round-trips through
	// `resolveConfig` / `fetchEnv` and the matching secrets get injected. Branch
	// lifecycle/compute is per-branch tuning, so it goes in the `branch` closure.
	const tuning: BranchTuning = {};
	if (parent) tuning.parent = parent.name;
	// Deliberately NOT emitting `ttl` from `branch.expiresAt`: policy `ttl` is a
	// creation-time *duration*, while `expiresAt` is an absolute timestamp. Feeding the
	// timestamp through `parseDuration` (in `resolveConfig`) would throw, breaking
	// `fetchEnv` / `neon dev` / `neon env pull` for any branch that has a TTL. The expiry
	// is reported faithfully on `branch.expiresAt` above.
	if (branch.protected) tuning.protected = true;
	if (endpoint) {
		const compute = endpointToComputeSettings(endpoint, project);
		if (compute) tuning.postgres = { computeSettings: compute };
	}
	// Buckets round-trip cleanly (name + access level), so they belong in the config the
	// env path resolves from — this is what lets `neon dev` / `neon env pull` inject the
	// branch's object-storage credentials (AWS_*) with no local neon.ts. Functions are
	// deliberately NOT emitted here (they can't round-trip: the remote has no `source`
	// path) and neither is the AI Gateway (no branch-level enabled state to detect, only a
	// credential) — both would otherwise turn a read-back into a bogus policy declaration.
	const bucketDefs: Record<string, { access: BucketAccessLevel }> = {};
	for (const b of previewState?.buckets ?? []) {
		bucketDefs[b.name] = { access: b.accessLevel };
	}
	const policyPreview: NonNullable<Config["preview"]> = {};
	const realtime = previewState?.realtime;
	if (realtime?.enabled) {
		// An empty list allows every origin, which is what `realtime: true` gets by default.
		policyPreview.realtime = realtime.allowedOrigins?.length
			? { allowedOrigins: [...realtime.allowedOrigins] }
			: true;
	}
	if (Object.keys(bucketDefs).length > 0) policyPreview.buckets = bucketDefs;
	const authEnabled = previewState?.authEnabled === true;
	const dataApi = previewState?.dataApi
		? pulledDataApiConfig(previewState.dataApi, authEnabled)
		: previewState?.dataApiEnabled
			? true
			: undefined;
	const config: Config = {
		...(authEnabled ? { auth: true } : {}),
		...(dataApi !== undefined ? { dataApi } : {}),
		...(Object.keys(policyPreview).length > 0
			? { preview: policyPreview }
			: {}),
		...(Object.keys(tuning).length > 0 ? { branch: () => tuning } : {}),
	};
	const result: PulledBranchConfig = {
		project: {
			id: project.id,
			name: project.name,
			region: project.regionId,
			pgVersion: project.pgVersion,
			...(project.orgId ? { orgId: project.orgId } : {}),
		},
		branch: {
			id: branch.id,
			name: branch.name,
			...(parent ? { parent: parent.name } : {}),
			isDefault: branch.isDefault,
			protected: branch.protected,
			...(branch.expiresAt ? { expiresAt: branch.expiresAt } : {}),
		},
		config,
	};
	const preview = previewState ? buildPulledPreview(previewState) : undefined;
	if (preview) result.preview = preview;
	return result;
}

/**
 * Reverse-engineer the {@link PulledPreview} from remote snapshots. Returns `undefined` when
 * the branch has no Preview features so the field can be omitted entirely.
 */
function buildPulledPreview(state: {
	buckets: NeonBucketSnapshot[];
	functions: NeonFunctionSnapshot[];
	credentials?: NeonCredentialMeta[];
}): PulledPreview | undefined {
	const credentials = state.credentials ?? [];
	if (
		state.buckets.length === 0 &&
		state.functions.length === 0 &&
		credentials.length === 0
	) {
		return undefined;
	}
	return {
		buckets: state.buckets.map((b) => ({
			name: b.name,
			access: b.accessLevel,
		})),
		functions: state.functions.map((f) => ({
			slug: f.slug,
			name: f.name,
		})),
		credentials,
	};
}

function resolveBranch(
	branchId: string,
	branches: NeonBranchSnapshot[],
): NeonBranchSnapshot {
	const match = branches.find((b) => b.id === branchId);
	if (match) return match;
	throw new PlatformError(
		ErrorCode.BranchNotFound,
		[
			`pullConfig: branch id ${JSON.stringify(branchId)} not found on project.`,
			`Available branches: ${branches.map((b) => `${b.name} (${b.id})`).join(", ") || "(none)"}.`,
		].join(" "),
		{
			details: {
				branchId,
				available: branches.map((b) => b.id),
			},
		},
	);
}

function endpointToComputeSettings(
	endpoint: NeonEndpointSnapshot,
	project: NeonProjectSnapshot,
): ComputeSettings | undefined {
	const defaults = project.defaultEndpointSettings;
	const out: ComputeSettings = {};
	if (
		endpoint.autoscalingLimitMinCu !== undefined &&
		endpoint.autoscalingLimitMinCu !== defaults?.autoscalingLimitMinCu
	) {
		out.autoscalingLimitMinCu = endpoint.autoscalingLimitMinCu;
	}
	if (
		endpoint.autoscalingLimitMaxCu !== undefined &&
		endpoint.autoscalingLimitMaxCu !== defaults?.autoscalingLimitMaxCu
	) {
		out.autoscalingLimitMaxCu = endpoint.autoscalingLimitMaxCu;
	}
	if (
		endpoint.suspendTimeout !== undefined &&
		endpoint.suspendTimeout !== defaults?.suspendTimeout
	) {
		out.suspendTimeout = endpoint.suspendTimeout;
	}
	return Object.keys(out).length > 0 ? out : undefined;
}
